void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (2. * fragCoord-iResolution.xy) / iResolution.y;
    vec3 color = vec3(0);
    const float PI = 3.14159265;
    const float G = sqrt(5.) * .5 + .5;
    vec2 ar = vec2(atan(uv.y, uv.x), length(uv));
    vec3 c1 = cos(2. * PI * iTime+1./ar.y - ar.x*vec3(1,2,3));
    vec3 c2 = cos(1. * PI * iTime+G/ar.y*vec3(1.7,.5,1.) - ar.x*vec3(2,3,1));
    vec3 c3 = cos(2. * PI * (iTime + sin(ar.x*6. - iTime)*(cos(iTime)*.5+.5)) + ar.x +6./ar.y*vec3(.3,.5,.8));
    vec3 c4 = cos((G * PI * iTime)*vec3(.7,1,1.3)+4./ar.y - 1.*ar.x*vec3(3,1,2));
    color +=      exp(-5. * (.5+.5*c1) * exp(-.2/ar.y));
    color += .075*exp(-4. * (sqrt(c2*c2+.125)-.25) * exp(-.2/ar.y));
    color += .025*exp(-4. * (.5+.5*c3) * exp(-.2/ar.y));
    color += .050*exp(-4. * (sqrt(c4*c4+.25)-.5) * exp(-.2/ar.y));
    color *= 1.025-.15*dot(uv, uv);
    fragColor = vec4(pow(color, vec3(1./2.2)), 1);
}
